484	static bool contains(SmallPtrSetImpl<ConstantExpr *> &Cache, ConstantExpr *Expr,
485	                     Constant *C) {
486	  if (!Cache.insert(Expr).second)
487	    return false;
488	
489	  for (auto &O : Expr->operands()) {
490	    if (O == C)
491	      return true;
492	    auto *CE = dyn_cast<ConstantExpr>(O);
