506	  if (!C)
507	    return false;
508	
509	  auto *CE = dyn_cast<ConstantExpr>(Expr);
510	  if (!CE)
511	    return false;
512	
513	  SmallPtrSet<ConstantExpr *, 4> Cache;
514	  return contains(Cache, CE, C);
