831	
832	bool Value::canBeFreed() const {
833	  assert(getType()->isPointerTy());
834	
835	  // Cases that can simply never be deallocated
836	  // *) Constants aren't allocated per se, thus not deallocated either.
837	  if (isa<Constant>(this))
838	    return false;
839	
840	  // Allocas cannot be freed: They remain dereferenceable after lifetime.end,
841	  // in the sense that they can be loaded from without UB. They only become
842	  // non-writable, which is not tracked by this API.
843	  if (isa<AllocaInst>(this))
844	    return false;
845	
846	  // Handle byval/byref/sret/inalloca/preallocated arguments.  The storage
847	  // lifetime is guaranteed to be longer than the callee's lifetime.
848	  if (auto *A = dyn_cast<Argument>(this)) {
849	    if (A->hasPointeeInMemoryValueAttr())
850	      return false;
851	    // A nofree function can not free (including via synchronization) any
852	    // allocations that existed prior to the call, but may free allocations
853	    // created inside the function. This logic is limited to argument pointers,
854	    // as they definitely exist prior to the call.
855	    const Function *F = A->getParent();
856	    if (F->doesNotFreeMemory())
857	      return false;
858	
859	    // nofree on the argument ensures that it cannot be freed through that
860	    // pointer. noalias additionally ensures that it can't be freed through
861	    // another pointer to the same allocation. Readonly implies nofree.
862	    if ((A->hasNoFreeAttr() || A->onlyReadsMemory()) && A->hasNoAliasAttr())
863	      return false;
864	  }
865	
866	  if (auto *ITP = dyn_cast<IntToPtrInst>(this);
867	      ITP && ITP->hasMetadata(LLVMContext::MD_nofree))
868	    return false;
869	
870	  const Function *F = nullptr;
871	  if (auto *I = dyn_cast<Instruction>(this))
872	    F = I->getFunction();
873	  if (auto *A = dyn_cast<Argument>(this))
874	    F = A->getParent();
875	
876	  if (!F)
877	    return true;
878	
879	  // With garbage collection, deallocation typically occurs solely at or after
880	  // safepoints.  If we're compiling for a collector which uses the
881	  // gc.statepoint infrastructure, safepoints aren't explicitly present
882	  // in the IR until after lowering from abstract to physical machine model.
883	  // The collector could chose to mix explicit deallocation and gc'd objects
884	  // which is why we need the explicit opt in on a per collector basis.
885	  if (!F->hasGC())
886	    return true;
887	
888	  const auto &GCName = F->getGC();
889	  if (GCName == "statepoint-example") {
890	    auto *PT = cast<PointerType>(this->getType());
891	    if (PT->getAddressSpace() != 1)
892	      // For the sake of this example GC, we arbitrarily pick addrspace(1) as
893	      // our GC managed heap.  This must match the same check in
894	      // RewriteStatepointsForGC (and probably needs better factored.)
895	      return true;
896	
897	    // It is cheaper to scan for a declaration than to scan for a use in this
898	    // function.  Note that gc.statepoint is a type overloaded function so the
899	    // usual trick of requesting declaration of the intrinsic from the module
900	    // doesn't work.
901	    for (auto &Fn : *F->getParent())
902	      if (Fn.getIntrinsicID() == Intrinsic::experimental_gc_statepoint)
903	        return true;
904	    return false;
905	  }
906	  return true;
907	}
908	
909	uint64_t Value::getPointerDereferenceableBytes(const DataLayout &DL,
910	                                               bool &CanBeNull,
911	                                               bool *CanBeFreed) const {
912	  assert(getType()->isPointerTy() && "must be pointer");
913	
914	  uint64_t DerefBytes = 0;
915	  CanBeNull = false;
916	  bool CanNotBeFreed = false;
917	  if (const Argument *A = dyn_cast<Argument>(this)) {
918	    DerefBytes = A->getDereferenceableBytes();
919	    if (DerefBytes == 0) {
920	      // Handle byval/byref/inalloca/preallocated arguments
921	      if (Type *ArgMemTy = A->getPointeeInMemoryValueType()) {
922	        if (ArgMemTy->isSized()) {
923	          // FIXME: Why isn't this the type alloc size?
924	          DerefBytes = DL.getTypeStoreSize(ArgMemTy).getKnownMinValue();
925	        }
926	      }
927	    }
928	
929	    if (DerefBytes == 0) {
930	      DerefBytes = A->getDereferenceableOrNullBytes();
931	      CanBeNull = true;
932	    }
933	  } else if (const auto *Call = dyn_cast<CallBase>(this)) {
934	    DerefBytes = Call->getRetDereferenceableBytes();
935	    if (DerefBytes == 0) {
936	      DerefBytes = Call->getRetDereferenceableOrNullBytes();
937	      CanBeNull = true;
938	    }
939	  } else if (const LoadInst *LI = dyn_cast<LoadInst>(this)) {
940	    if (MDNode *MD = LI->getMetadata(LLVMContext::MD_dereferenceable)) {
941	      ConstantInt *CI = mdconst::extract<ConstantInt>(MD->getOperand(0));
942	      DerefBytes = CI->getLimitedValue();
943	    }
944	    if (DerefBytes == 0) {
945	      if (MDNode *MD =
946	              LI->getMetadata(LLVMContext::MD_dereferenceable_or_null)) {
947	        ConstantInt *CI = mdconst::extract<ConstantInt>(MD->getOperand(0));
948	        DerefBytes = CI->getLimitedValue();
949	      }
950	      CanBeNull = true;
951	    }
952	  } else if (auto *IP = dyn_cast<IntToPtrInst>(this)) {
953	    if (MDNode *MD = IP->getMetadata(LLVMContext::MD_dereferenceable)) {
954	      ConstantInt *CI = mdconst::extract<ConstantInt>(MD->getOperand(0));
955	      DerefBytes = CI->getLimitedValue();
956	    }
957	    if (DerefBytes == 0) {
958	      if (MDNode *MD =
959	              IP->getMetadata(LLVMContext::MD_dereferenceable_or_null)) {
960	        ConstantInt *CI = mdconst::extract<ConstantInt>(MD->getOperand(0));
961	        DerefBytes = CI->getLimitedValue();
962	      }
963	      CanBeNull = true;
964	    }
965	  } else if (auto *AI = dyn_cast<AllocaInst>(this)) {
966	    if (std::optional<TypeSize> Size = AI->getAllocationSize(DL)) {
967	      DerefBytes = Size->getKnownMinValue();
968	      CanBeNull = false;
969	      CanNotBeFreed = true;
970	    }
971	  } else if (auto *GV = dyn_cast<GlobalVariable>(this)) {
972	    if (GV->getValueType()->isSized() && !GV->hasExternalWeakLinkage()) {
973	      // TODO: Don't outright reject hasExternalWeakLinkage but set the
974	      // CanBeNull flag.
975	      DerefBytes = DL.getTypeStoreSize(GV->getValueType()).getFixedValue();
976	      CanBeNull = false;
977	      CanNotBeFreed = true;
978	    }
979	  }
980	
981	  if (CanBeFreed) {
982	    // Call canBeFreed() only if there are dereferenceable bytes and it's not
983	    // one of the cases that can never be freed.
984	    if (!CanNotBeFreed && DerefBytes != 0)
985	      *CanBeFreed = UseDerefAtPointSemantics && canBeFreed();
986	    else
987	      *CanBeFreed = false;
988	  }
989	
990	  return DerefBytes;
991	}
