993	Align Value::getPointerAlignment(const DataLayout &DL) const {
994	  assert(getType()->isPointerTy() && "must be pointer");
995	  if (const Function *F = dyn_cast<Function>(this)) {
996	    Align FunctionPtrAlign = DL.getFunctionPtrAlign().valueOrOne();
997	    switch (DL.getFunctionPtrAlignType()) {
998	    case DataLayout::FunctionPtrAlignType::Independent:
999	      return FunctionPtrAlign;
1000	    case DataLayout::FunctionPtrAlignType::MultipleOfFunctionAlign:
1001	      return std::max(FunctionPtrAlign, F->getAlign().valueOrOne());
1002	    }
1003	    llvm_unreachable("Unhandled FunctionPtrAlignType");
1004	  } else if (auto *GVar = dyn_cast<GlobalVariable>(this)) {
1005	    const MaybeAlign Alignment(GVar->getAlign());
1006	    if (!Alignment) {
1007	      Type *ObjectType = GVar->getValueType();
1008	      if (ObjectType->isSized()) {
1009	        // If the object is defined in the current Module, we'll be giving
1010	        // it the preferred alignment. Otherwise, we have to assume that it
1011	        // may only have the minimum ABI alignment.
1012	        if (GVar->isStrongDefinitionForLinker())
1013	          return DL.getPreferredAlign(GVar);
1014	        else
1015	          return DL.getABITypeAlign(ObjectType);
1016	      }
1017	    }
1018	    return Alignment.valueOrOne();
1019	  } else if (const Argument *A = dyn_cast<Argument>(this)) {
1020	    const MaybeAlign Alignment = A->getParamAlign();
1021	    if (!Alignment && A->hasStructRetAttr()) {
1022	      // An sret parameter has at least the ABI alignment of the return type.
1023	      Type *EltTy = A->getParamStructRetType();
1024	      if (EltTy->isSized())
1025	        return DL.getABITypeAlign(EltTy);
1026	    }
1027	    return Alignment.valueOrOne();
1028	  } else if (const AllocaInst *AI = dyn_cast<AllocaInst>(this)) {
1029	    return AI->getAlign();
1030	  } else if (const auto *Call = dyn_cast<CallBase>(this)) {
1031	    MaybeAlign Alignment = Call->getRetAlign();
1032	    if (!Alignment && Call->getCalledFunction())
1033	      Alignment = Call->getCalledFunction()->getAttributes().getRetAlignment();
1034	    return Alignment.valueOrOne();
1035	  } else if (const LoadInst *LI = dyn_cast<LoadInst>(this)) {
1036	    if (MDNode *MD = LI->getMetadata(LLVMContext::MD_align)) {
1037	      ConstantInt *CI = mdconst::extract<ConstantInt>(MD->getOperand(0));
1038	      return Align(CI->getLimitedValue());
1039	    }
1040	  } else if (auto *CE = dyn_cast<ConstantExpr>(this)) {
1041	    // Determine the alignment of inttoptr(C).
1042	    if (CE->getOpcode() == Instruction::IntToPtr &&
1043	        isa<ConstantInt>(CE->getOperand(0))) {
1044	      ConstantInt *IntPtr = cast<ConstantInt>(CE->getOperand(0));
1045	      size_t TrailingZeros = IntPtr->getValue().countr_zero();
1046	      // While the actual alignment may be large, elsewhere we have
1047	      // an arbitrary upper alignmet limit, so let's clamp to it.
1048	      return Align(TrailingZeros < Value::MaxAlignmentExponent
1049	                       ? uint64_t(1) << TrailingZeros
1050	                       : Value::MaximumAlignment);
1051	    }
1052	  }
1053	  return Align(1);
1054	}
