1056	static std::optional<int64_t>
1057	getOffsetFromIndex(const GEPOperator *GEP, unsigned Idx, const DataLayout &DL) {
1058	  // Skip over the first indices.
1059	  gep_type_iterator GTI = gep_type_begin(GEP);
1060	  for (unsigned i = 1; i != Idx; ++i, ++GTI)
1061	    /*skip along*/;
1062	
1063	  // Compute the offset implied by the rest of the indices.
1064	  int64_t Offset = 0;
1065	  for (unsigned i = Idx, e = GEP->getNumOperands(); i != e; ++i, ++GTI) {
1066	    ConstantInt *OpC = dyn_cast<ConstantInt>(GEP->getOperand(i));
1067	    if (!OpC)
1068	      return std::nullopt;
1069	    if (OpC->isZero())
1070	      continue; // No offset.
1071	
1072	    // Handle struct indices, which add their field offset to the pointer.
1073	    if (StructType *STy = GTI.getStructTypeOrNull()) {
1074	      Offset += DL.getStructLayout(STy)->getElementOffset(OpC->getZExtValue());
1075	      continue;
1076	    }
1077	
1078	    // Otherwise, we have a sequential type like an array or fixed-length
1079	    // vector. Multiply the index by the ElementSize.
1080	    TypeSize Size = GTI.getSequentialElementStride(DL);
1081	    if (Size.isScalable())
1082	      return std::nullopt;
1083	    Offset += Size.getFixedValue() * OpC->getSExtValue();
1084	  }
1085	
1086	  return Offset;
1087	}
