1089	std::optional<int64_t> Value::getPointerOffsetFrom(const Value *Other,
1090	                                                   const DataLayout &DL) const {
1091	  const Value *Ptr1 = Other;
1092	  const Value *Ptr2 = this;
1093	  APInt Offset1(DL.getIndexTypeSizeInBits(Ptr1->getType()), 0);
1094	  APInt Offset2(DL.getIndexTypeSizeInBits(Ptr2->getType()), 0);
1095	  Ptr1 = Ptr1->stripAndAccumulateConstantOffsets(DL, Offset1, true);
1096	  Ptr2 = Ptr2->stripAndAccumulateConstantOffsets(DL, Offset2, true);
1097	
1098	  // Handle the trivial case first.
1099	  if (Ptr1 == Ptr2)
1100	    return Offset2.getSExtValue() - Offset1.getSExtValue();
1101	
1102	  const GEPOperator *GEP1 = dyn_cast<GEPOperator>(Ptr1);
1103	  const GEPOperator *GEP2 = dyn_cast<GEPOperator>(Ptr2);
1104	
1105	  // Right now we handle the case when Ptr1/Ptr2 are both GEPs with an identical
1106	  // base.  After that base, they may have some number of common (and
1107	  // potentially variable) indices.  After that they handle some constant
1108	  // offset, which determines their offset from each other.  At this point, we
1109	  // handle no other case.
1110	  if (!GEP1 || !GEP2 || GEP1->getOperand(0) != GEP2->getOperand(0) ||
1111	      GEP1->getSourceElementType() != GEP2->getSourceElementType())
1112	    return std::nullopt;
1113	
1114	  // Skip any common indices and track the GEP types.
1115	  unsigned Idx = 1;
1116	  for (; Idx != GEP1->getNumOperands() && Idx != GEP2->getNumOperands(); ++Idx)
1117	    if (GEP1->getOperand(Idx) != GEP2->getOperand(Idx))
1118	      break;
1119	
1120	  auto IOffset1 = getOffsetFromIndex(GEP1, Idx, DL);
1121	  auto IOffset2 = getOffsetFromIndex(GEP2, Idx, DL);
1122	  if (!IOffset1 || !IOffset2)
1123	    return std::nullopt;
1124	  return *IOffset2 - *IOffset1 + Offset2.getSExtValue() -
1125	         Offset1.getSExtValue();
1126	}
