1136	void Value::reverseUseList() {
1137	  if (!UseList || !UseList->Next)
1138	    // No need to reverse 0 or 1 uses.
1139	    return;
1140	
1141	  Use *Head = UseList;
1142	  Use *Current = UseList->Next;
1143	  Head->Next = nullptr;
1144	  while (Current) {
1145	    Use *Next = Current->Next;
1146	    Current->Next = Head;
1147	    Head->Prev = &Current->Next;
1148	    Head = Current;
1149	    Current = Next;
1150	  }
1151	  UseList = Head;
1152	  Head->Prev = &UseList;
1153	}
