1191	
1192	void ValueHandleBase::AddToUseList() {
1193	  assert(getValPtr() && "Null pointer doesn't have a use list!");
1194	
1195	  LLVMContextImpl *pImpl = getValPtr()->getContext().pImpl;
1196	
1197	  if (getValPtr()->HasValueHandle) {
1198	    // If this value already has a ValueHandle, then it must be in the
1199	    // ValueHandles map already.
1200	    ValueHandleBase *&Entry = pImpl->ValueHandles[getValPtr()];
1201	    assert(Entry && "Value doesn't have any handles?");
1202	    AddToExistingUseList(&Entry);
1203	    return;
1204	  }
1205	
1206	  // Ok, it doesn't have any handles yet, so we must insert it into the
1207	  // DenseMap.  However, doing this insertion could cause the DenseMap to
1208	  // reallocate itself, which would invalidate all of the PrevP pointers that
1209	  // point into the old table.  Handle this by checking for reallocation and
1210	  // updating the stale pointers only if needed.
1211	  DenseMap<Value*, ValueHandleBase*> &Handles = pImpl->ValueHandles;
1212	  const void *OldBucketPtr = Handles.getPointerIntoBucketsArray();
1213	
1214	  ValueHandleBase *&Entry = Handles[getValPtr()];
1215	  assert(!Entry && "Value really did already have handles?");
1216	  AddToExistingUseList(&Entry);
1217	  getValPtr()->HasValueHandle = true;
1218	
1219	  // If reallocation didn't happen or if this was the first insertion, don't
1220	  // walk the table.
1221	  if (Handles.isPointerIntoBucketsArray(OldBucketPtr) ||
1222	      Handles.size() == 1) {
1223	    return;
1224	  }
1225	
1226	  // Okay, reallocation did happen.  Fix the Prev Pointers.
1227	  for (auto I = Handles.begin(), E = Handles.end(); I != E; ++I) {
1228	    assert(I->second && I->first == I->second->getValPtr() &&
1229	           "List invariant broken!");
1230	    I->second->setPrevPtr(&I->second);
1231	  }
1232	}
1233	
1234	void ValueHandleBase::RemoveFromUseList() {
1235	  assert(getValPtr() && getValPtr()->HasValueHandle &&
1236	         "Pointer doesn't have a use list!");
1237	
1238	  // Unlink this from its use list.
1239	  ValueHandleBase **PrevPtr = getPrevPtr();
1240	  assert(*PrevPtr == this && "List invariant broken");
1241	
1242	  *PrevPtr = Next;
1243	  if (Next) {
1244	    assert(Next->getPrevPtr() == &Next && "List invariant broken");
1245	    Next->setPrevPtr(PrevPtr);
1246	    return;
1247	  }
1248	
1249	  // If the Next pointer was null, then it is possible that this was the last
1250	  // ValueHandle watching VP.  If so, delete its entry from the ValueHandles
1251	  // map.
1252	  LLVMContextImpl *pImpl = getValPtr()->getContext().pImpl;
1253	  DenseMap<Value*, ValueHandleBase*> &Handles = pImpl->ValueHandles;
1254	  if (Handles.isPointerIntoBucketsArray(PrevPtr)) {
1255	    // TODO: Remove the only user of DenseMap's callback erase.
1256	    Handles.erase(getValPtr(), [](auto &Bucket) {
1257	      Bucket.second->setPrevPtr(&Bucket.second);
1258	    });
1259	    getValPtr()->HasValueHandle = false;
1260	  }
1261	}
1262	
1263	void ValueHandleBase::ValueIsDeleted(Value *V) {
1264	  assert(V->HasValueHandle && "Should only be called if ValueHandles present");
1265	
1266	  // Get the linked list base, which is guaranteed to exist since the
1267	  // HasValueHandle flag is set.
1268	  LLVMContextImpl *pImpl = V->getContext().pImpl;
1269	  ValueHandleBase *Entry = pImpl->ValueHandles[V];
1270	  assert(Entry && "Value bit set but no entries exist");
1271	
1272	  // We use a local ValueHandleBase as an iterator so that ValueHandles can add
1273	  // and remove themselves from the list without breaking our iteration.  This
1274	  // is not really an AssertingVH; we just have to give ValueHandleBase a kind.
1275	  // Note that we deliberately do not the support the case when dropping a value
1276	  // handle results in a new value handle being permanently added to the list
1277	  // (as might occur in theory for CallbackVH's): the new value handle will not
1278	  // be processed and the checking code will mete out righteous punishment if
1279	  // the handle is still present once we have finished processing all the other
1280	  // value handles (it is fine to momentarily add then remove a value handle).
1281	  for (ValueHandleBase Iterator(Assert, *Entry); Entry; Entry = Iterator.Next) {
1282	    Iterator.RemoveFromUseList();
1283	    Iterator.AddToExistingUseListAfter(Entry);
1284	    assert(Entry->Next == &Iterator && "Loop invariant broken.");
1285	
1286	    switch (Entry->getKind()) {
1287	    case Assert:
1288	      break;
1289	    case Weak:
1290	    case WeakTracking:
1291	      // WeakTracking and Weak just go to null, which unlinks them
1292	      // from the list.
1293	      Entry->operator=(nullptr);
1294	      break;
1295	    case Callback:
1296	      // Forward to the subclass's implementation.
1297	      static_cast<CallbackVH*>(Entry)->deleted();
1298	      break;
1299	    }
1300	  }
1301	
1302	  // All callbacks, weak references, and assertingVHs should be dropped by now.
1303	  if (V->HasValueHandle) {
1304	#ifndef NDEBUG      // Only in +Asserts mode...
1305	    dbgs() << "While deleting: " << *V->getType() << " %" << V->getName()
1306	           << "\n";
1307	    if (pImpl->ValueHandles[V]->getKind() == Assert)
1308	      llvm_unreachable("An asserting value handle still pointed to this"
1309	                       " value!");
1310	
1311	#endif
1312	    llvm_unreachable("All references to V were not removed?");
1313	  }
1314	}
1315	
1316	void ValueHandleBase::ValueIsRAUWd(Value *Old, Value *New) {
1317	  assert(Old->HasValueHandle &&"Should only be called if ValueHandles present");
1318	  assert(Old != New && "Changing value into itself!");
1319	  assert(Old->getType() == New->getType() &&
1320	         "replaceAllUses of value with new value of different type!");
1321	
1322	  // Get the linked list base, which is guaranteed to exist since the
1323	  // HasValueHandle flag is set.
1324	  LLVMContextImpl *pImpl = Old->getContext().pImpl;
1325	  ValueHandleBase *Entry = pImpl->ValueHandles[Old];
1326	
1327	  assert(Entry && "Value bit set but no entries exist");
1328	
1329	  // We use a local ValueHandleBase as an iterator so that
1330	  // ValueHandles can add and remove themselves from the list without
1331	  // breaking our iteration.  This is not really an AssertingVH; we
1332	  // just have to give ValueHandleBase some kind.
1333	  for (ValueHandleBase Iterator(Assert, *Entry); Entry; Entry = Iterator.Next) {
1334	    Iterator.RemoveFromUseList();
1335	    Iterator.AddToExistingUseListAfter(Entry);
1336	    assert(Entry->Next == &Iterator && "Loop invariant broken.");
1337	
1338	    switch (Entry->getKind()) {
1339	    case Assert:
1340	    case Weak:
1341	      // Asserting and Weak handles do not follow RAUW implicitly.
1342	      break;
1343	    case WeakTracking:
1344	      // Weak goes to the new value, which will unlink it from Old's list.
1345	      Entry->operator=(New);
1346	      break;
1347	    case Callback:
1348	      // Forward to the subclass's implementation.
1349	      static_cast<CallbackVH*>(Entry)->allUsesReplacedWith(New);
1350	      break;
1351	    }
1352	  }
1353	
1354	#ifndef NDEBUG
1355	  // If any new weak value handles were added while processing the
1356	  // list, then complain about it now.
1357	  if (Old->HasValueHandle)
1358	    for (Entry = pImpl->ValueHandles[Old]; Entry; Entry = Entry->Next)
1359	      switch (Entry->getKind()) {
1360	      case WeakTracking:
1361	        dbgs() << "After RAUW from " << *Old->getType() << " %"
1362	               << Old->getName() << " to " << *New->getType() << " %"
1363	               << New->getName() << "\n";
1364	        llvm_unreachable(
1365	            "A weak tracking value handle still pointed to the old value!\n");
1366	      default:
1367	        break;
1368	      }
1369	#endif
1370	}
1371	
1372	// Pin the vtable to this file.
1373	void CallbackVH::anchor() {}
1374

